const _apiInflight=new Map(),_apiCache=new Map();
async function api(path,opt={}){
  const {timeout=25000,cacheTtl=0,...requestOpt}=opt;
  const method=String(requestOpt.method||'GET').toUpperCase();
  const cacheKey=method==='GET'?String(path):'';
  if(cacheKey&&cacheTtl>0){const hit=_apiCache.get(cacheKey);if(hit&&Date.now()-hit.t<cacheTtl)return hit.v}
  if(cacheKey&&_apiInflight.has(cacheKey))return _apiInflight.get(cacheKey);
  const run=(async()=>{const ctrl=new AbortController();const timer=setTimeout(()=>ctrl.abort(),Math.max(3000,Number(timeout)||25000));let r;try{r=await fetch(path,{credentials:'include',...requestOpt,signal:requestOpt.signal||ctrl.signal,headers:{...(requestOpt.body instanceof FormData?{}:{'content-type':'application/json'}),...(state.user&&state.organizationId?{'x-organization-id':state.organizationId}:{}),...(requestOpt.headers||{})}})}catch(e){if(e?.name==='AbortError')throw new Error('Yêu cầu mất nhiều thời gian hơn bình thường. Vui lòng thử lại.');throw e}finally{clearTimeout(timer)}let j={};try{j=await r.json()}catch{}if(!r.ok||j.ok===false){const fallback=r.status>=500?'Đã xảy ra sự cố tạm thời. Vui lòng thử lại sau.':`Yêu cầu không được xử lý (HTTP ${r.status}).`;const detail=[j?.code&&`Mã: ${j.code}`,j?.area&&`Khu vực: ${j.area}`,j?.method&&j?.path&&`API: ${j.method} ${j.path}`,j?.request_id&&`Request ID: ${j.request_id}`].filter(Boolean).join(' · ');const e=new Error(`${j.message||fallback}${detail?` — ${detail}`:''}`);e.data=j;e.status=r.status;throw e}if(cacheKey&&cacheTtl>0)_apiCache.set(cacheKey,{t:Date.now(),v:j});if(method!=='GET')_apiCache.clear();return j})();
  if(cacheKey)_apiInflight.set(cacheKey,run);try{return await run}finally{if(cacheKey)_apiInflight.delete(cacheKey)}
}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function roleLabel(r=''){return ({student:'Học viên',assistant:'Trợ giảng',teacher:'Giáo viên',account_admin:'Quản trị tài khoản',school_admin:'Quản trị trường học',super_admin:'Quản trị hệ thống',guest:'Khách'})[String(r)]||'Thành viên'}
function lastNameInitial(name=''){const parts=String(name||'').trim().split(/\s+/).filter(Boolean);return (parts.at(-1)?.[0]||'T').toUpperCase()}
function displayInitial(name=''){const parts=String(name).trim().split(/\s+/).filter(Boolean);return (parts.at(-1)?.[0]||'?').toLocaleUpperCase('vi-VN')}
function avatarMarkup(user,size='md'){const initial=displayInitial(user?.full_name||user?.display_name||user?.guest_name||'');const uid=user?.id||user?.user_id;if(user?.avatar_key&&uid)return `<span class="user-avatar ${size} has-image"><img src="/api/avatar/${encodeURIComponent(uid)}" alt="" loading="lazy"></span>`;return `<span class="user-avatar ${size}" aria-hidden="true">${esc(initial)}</span>`}
function activeOrg(){return localStorage.getItem('slc_org')||'sky-first'}
function safeRichHtml(html=''){const doc=new DOMParser().parseFromString(String(html),'text/html');doc.querySelectorAll('script,style,iframe,object,embed,link,meta').forEach(x=>x.remove());doc.querySelectorAll('*').forEach(el=>{[...el.attributes].forEach(a=>{const n=a.name.toLowerCase(),v=a.value.trim().toLowerCase();if(n.startsWith('on')||n==='srcdoc'||((n==='href'||n==='src')&&v.startsWith('javascript:')))el.removeAttribute(a.name)})});return doc.body.innerHTML}
async function cropAvatarFile(file){
  if(!file)return null;const url=URL.createObjectURL(file);const img=new Image();img.src=url;await img.decode();
  return await new Promise(resolve=>{const d=document.createElement('dialog');d.className='avatar-crop-dialog';d.innerHTML=`<form method="dialog"><h3>Cắt ảnh đại diện</h3><div class="avatar-crop-preview"><canvas width="420" height="420"></canvas></div><label>Thu phóng <input type="range" min="1" max="3" step="0.05" value="1" data-zoom></label><div class="toolbar"><button value="cancel">Hủy</button><button value="save" class="btn primary">Dùng ảnh này</button></div></form>`;document.body.appendChild(d);const c=d.querySelector('canvas'),ctx=c.getContext('2d'),z=d.querySelector('[data-zoom]');const draw=()=>{const zoom=Number(z.value),base=Math.max(c.width/img.width,c.height/img.height)*zoom,w=img.width*base,h=img.height*base;ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(img,(c.width-w)/2,(c.height-h)/2,w,h)};z.oninput=draw;draw();d.onclose=()=>{if(d.returnValue!=='save'){URL.revokeObjectURL(url);d.remove();return resolve(null)}c.toBlob(blob=>{URL.revokeObjectURL(url);d.remove();resolve(blob)},'image/webp',.9)};d.showModal()})
}
function downloadJson(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
