  const peers=new Map(), peerMeta=new Map(), remoteSfuStreams=new Map(), remotePeerStreams=new Map(), pendingPeerIce=new Map(); let selfPeerId='',ws=null,wsOnline=false,closing=false,chatPoll=null,sfuTrackPoll=null,fallbackPoll=null,fallbackActive=false,fallbackAfter=0,fallbackPrimed=false,fallbackSelfKey='',lastHttpChatKey='',sfu=null,classroomTools=null,reconnectAttempt=0,initialMediaApplied=false;
  const localVideo=$('#localVideo'),placeholder=$('#localPlaceholder'); localVideo.srcObject=localStream;
