    $('#toggleMic').classList.toggle('off',!micOn); $('#toggleMic small').textContent=micOn?'Tắt mic':'Bật mic';
    $('#toggleCam').classList.toggle('off',!camOn); $('#toggleCam small').textContent=camOn?'Tắt cam':'Bật cam';
